package com.jian.scrcpy.net;import com.jian.scrcpy.protocol.*;import io.netty.bootstrap.Bootstrap;import io.netty.channel.*;import io.netty.channel.nio.NioIoHandler;import io.netty.channel.socket.nio.NioSocketChannel;import java.net.*;
public final class ScrcpyConnection implements AutoCloseable{private final EventLoopGroup group=new MultiThreadIoEventLoopGroup(NioIoHandler.newFactory());private final int port;private Channel video,audio,control;public ScrcpyConnection(int p){port=p;}private Channel connect(ChannelInitializer<Channel> i)throws Exception{return new Bootstrap().group(group).channel(NioSocketChannel.class).option(ChannelOption.TCP_NODELAY,true).handler(i).connect(new InetSocketAddress("127.0.0.1",port)).sync().channel();}public void open(ChannelInboundHandler vh,ChannelInboundHandler ah,ChannelInboundHandler ch)throws Exception{video=connect(new ChannelInitializer<>(){protected void initChannel(Channel c){c.pipeline().addLast(new ScrcpyMediaDecoder(),new ConfigPacketMerger(),vh);}});audio=connect(new ChannelInitializer<>(){protected void initChannel(Channel c){c.pipeline().addLast(new ScrcpyMediaDecoder(),ah);}});control=connect(new ChannelInitializer<>(){protected void initChannel(Channel c){c.pipeline().addLast(new DeviceMessageDecoder(),new ControlMessageEncoder(),ch);}});}public Channel control(){return control;}public void close(){for(var c:new Channel[]{video,audio,control})if(c!=null)c.close();group.shutdownGracefully();}}